def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves starting from any empty cell."""
    if K < 0:
        return 0

    n = H * W
    neighbors = [[] for _ in range(n)]
    empty = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            cell = r * W + c
            empty.append(cell)
            if r:
                neighbors[cell].append(cell - W)
            if r + 1 < H:
                neighbors[cell].append(cell + W)
            if c:
                neighbors[cell].append(cell - 1)
            if c + 1 < W:
                neighbors[cell].append(cell + 1)

    if K >= len(empty):
        return 0

    total = 0

    def visit(cell: int, used: int, left: int) -> int:
        if left == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not used & bit:
                count += visit(nxt, used | bit, left - 1)
        return count

    for start in empty:
        total += visit(start, 1 << start, K)
    return total

