def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves starting from any empty cell."""
    if K < 0:
        return 0

    n = H * W
    empty = [r * W + c for r in range(H) for c in range(W) if grid[r][c] == "."]
    if K >= len(empty):
        return 0

    neighbors = [[] for _ in range(n)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            cell = r * W + c
            if r and grid[r - 1][c] == ".":
                neighbors[cell].append(cell - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[cell].append(cell + W)
            if c and grid[r][c - 1] == ".":
                neighbors[cell].append(cell - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[cell].append(cell + 1)

    def visit(cell: int, used: int, left: int) -> int:
        if left == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not used & bit:
                count += visit(nxt, used | bit, left - 1)
        return count

    return sum(visit(start, 1 << start, K) for start in empty)

