from bisect import bisect_left


def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one letter change."""
    n = len(s)
    if k >= 26:
        return 1

    positions = [[] for _ in range(26)]
    for i, ch in enumerate(s):
        positions[ord(ch) - 97].append(i)

    # Greedy boundary from every possible starting position.
    nxt = [n] * n
    right = 0
    counts = [0] * 26
    distinct = 0
    for left in range(n):
        while right < n:
            c = ord(s[right]) - 97
            if counts[c] == 0 and distinct == k:
                break
            if counts[c] == 0:
                distinct += 1
            counts[c] += 1
            right += 1
        nxt[left] = right
        c = ord(s[left]) - 97
        counts[c] -= 1
        if counts[c] == 0:
            distinct -= 1

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = 1 + suffix[nxt[i]]

    best = suffix[0]

    def mask_for_interval(a, b):
        mask = 0
        for c, arr in enumerate(positions):
            j = bisect_left(arr, a)
            if j < len(arr) and arr[j] < b:
                mask |= 1 << c
        return mask

    start = 0
    prior = 0
    while start < n:
        end = nxt[start]
        for p in range(start, end):
            old = ord(s[p]) - 97
            old_positions = positions[old]
            first_old = bisect_left(old_positions, start)
            for replacement in range(26):
                if replacement == old:
                    continue
                lo, hi = p + 1, n
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    mask = mask_for_interval(start, mid)
                    last_old = bisect_left(old_positions, mid)
                    if last_old - first_old == 1:
                        mask &= ~(1 << old)
                    mask |= 1 << replacement
                    if mask.bit_count() <= k:
                        lo = mid
                    else:
                        hi = mid - 1
                best = max(best, prior + 1 + suffix[lo])
        prior += 1
        start = end
    return best

from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximum product <= limit."""
    # Each dictionary maps an alternating sum to the products reachable with that sum.
    # "even" and "odd" record the parity of the number of selected elements so far.
    even = {}
    odd = {}

    for value in nums:
        # Snapshot current states so this element is used at most once.
        even_items = [(total, tuple(products)) for total, products in even.items()]
        odd_items = [(total, tuple(products)) for total, products in odd.items()]

        # A subsequence can start with this element (its first sign is positive).
        if value <= limit:
            odd.setdefault(value, set()).add(value)

        # Appending after an even count uses the next positive sign.
        for total, products in even_items:
            next_total = total + value
            for product in products:
                next_product = product * value
                if next_product <= limit:
                    odd.setdefault(next_total, set()).add(next_product)

        # Appending after an odd count uses the next negative sign.
        for total, products in odd_items:
            next_total = total - value
            for product in products:
                next_product = product * value
                if next_product <= limit:
                    even.setdefault(next_total, set()).add(next_product)

    candidates = even.get(k, set()) | odd.get(k, set())
    return max(candidates) if candidates else -1

