def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353."""
    mod = 998244353
    if m == 1:
        return n % mod

    # A sequence has score product_p (1 + sum_i exponent_p(a_i)).
    # Expand this product over primes, then group primes whose exponent
    # contributions come from the same sequence position.
    primes = []
    for x in range(2, m + 1):
        is_prime = True
        for p in primes:
            if p * p > x:
                break
            if x % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(x)

    exponents = []
    for x in range(1, m + 1):
        row = []
        for p in primes:
            e = 0
            y = x
            while y % p == 0:
                e += 1
                y //= p
            row.append(e)
        exponents.append(row)

    prime_count = len(primes)
    block_weight = {}
    for mask in range(1, 1 << prime_count):
        weight = 0
        for row in exponents:
            term = 1
            for i in range(prime_count):
                if mask >> i & 1:
                    term *= row[i]
            weight += term
        block_weight[mask] = weight % mod

    # S_b = sum_{k=1}^n (k)_b * m^(k-b). Compute each needed sum
    # by powering the recurrence T_j(k+1) = m*T_j(k) + j*T_(j-1)(k).
    def falling_power_sum(b):
        size = b + 2
        acc_index = size - 1
        matrix = [[0] * size for _ in range(size)]
        for j in range(b + 1):
            matrix[j][j] = m % mod
            if j:
                matrix[j][j - 1] = j
        matrix[acc_index][acc_index] = 1
        matrix[acc_index][b] = m % mod
        if b:
            matrix[acc_index][b - 1] = b

        vector = [0] * size
        vector[0] = 1

        def multiply(a, c):
            out = [[0] * size for _ in range(size)]
            for i in range(size):
                for k in range(size):
                    if a[i][k]:
                        aik = a[i][k]
                        for j in range(size):
                            if c[k][j]:
                                out[i][j] = (out[i][j] + aik * c[k][j]) % mod
            return out

        def apply(a, v):
            return [sum(a[i][j] * v[j] for j in range(size)) % mod
                    for i in range(size)]

        power = n
        while power:
            if power & 1:
                vector = apply(matrix, vector)
            matrix = multiply(matrix, matrix)
            power >>= 1
        return vector[acc_index]

    sums = [falling_power_sum(b) for b in range(prime_count + 1)]
    answer = 0

    # Each partition of a selected subset of primes gives one term. A block
    # assigned to one position contributes sum_a product_p exponent_p(a);
    # distinct blocks choose distinct positions in (k)_b ways.
    def visit(index, blocks, weight):
        nonlocal answer
        if index == prime_count:
            answer = (answer + weight * sums[len(blocks)]) % mod
            return

        # This prime contributes the constant 1 in the product expansion.
        visit(index + 1, blocks, weight)

        bit = 1 << index
        # Or it contributes an exponent and joins an existing position block.
        for j, old_mask in enumerate(blocks):
            new_blocks = blocks.copy()
            new_blocks[j] = old_mask | bit
            visit(index + 1, new_blocks,
                  weight * block_weight[old_mask | bit] % mod)

        # Or it contributes an exponent at a new position.
        new_mask = bit
        visit(index + 1, blocks + [new_mask],
              weight * block_weight[new_mask] % mod)

    visit(0, [], 1)
    return answer

