from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the optimal modified tic-tac-toe game and return its winner."""
    values = tuple(value for row in grid for value in row)
    lines = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    all_cells = (1 << 9) - 1

    @lru_cache(maxsize=None)
    def play(takahashi: int, aoki: int) -> int:
        occupied = takahashi | aoki
        move = occupied.bit_count()

        if occupied == all_cells:
            score_difference = sum(
                values[i] for i in range(9) if takahashi & (1 << i)
            ) - sum(values[i] for i in range(9) if aoki & (1 << i))
            return 1 if score_difference > 0 else -1

        is_takahashi_turn = move % 2 == 0
        best = -2 if is_takahashi_turn else 2

        for cell in range(9):
            bit = 1 << cell
            if occupied & bit:
                continue

            if is_takahashi_turn:
                next_takahashi = takahashi | bit
                if any(next_takahashi & line == line for line in lines):
                    result = 1
                else:
                    result = play(next_takahashi, aoki)
                if result > best:
                    best = result
                    if best == 1:
                        break
            else:
                next_aoki = aoki | bit
                if any(next_aoki & line == line for line in lines):
                    result = -1
                else:
                    result = play(takahashi, next_aoki)
                if result < best:
                    best = result
                    if best == -1:
                        break

        return best

    return "Takahashi" if play(0, 0) == 1 else "Aoki"

def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum number of greedy partitions after at most one change."""
    n = len(s)

    def count_partitions(text):
        count = 0
        seen = set()
        for ch in text:
            seen.add(ch)
            if len(seen) > k:
                count += 1
                seen = {ch}
        return count + bool(seen)

    best = count_partitions(s)
    alphabet = set(s)
    if len(alphabet) < 26:
        alphabet.add(next(chr(c) for c in range(97, 123) if chr(c) not in alphabet))
    chars = list(alphabet)
    for i, old in enumerate(s):
        for ch in chars:
            if ch == old:
                continue
            changed = s[:i] + ch + s[i + 1:]
            best = max(best, count_partitions(changed))
    return best

