from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        # Even cells are horizontal strips; odd cells are vertical strips.
        return y % K if (i + (y // K)) % 2 == 0 else x % K

    sk = stripe(si, S_x, S_y)
    tk = stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    # For very distant cells the repeating checkerboard has an optimal
    # monotone route whose cost is the number of cell boundaries crossed.
    if (dx + 1) * (dy + 1) > 100_000:
        return dx + dy

    # A tile inside a macrocell is a point on a path of K tiles. A shortest
    # route inside that cell between stripe indices a and b costs |a-b|.
    # Only endpoint stripes and the two boundary stripes can matter to a
    # route that crosses between macrocells.
    vals = sorted({0, K - 1, sk, tk})
    vid = {v: n for n, v in enumerate(vals)}
    nvals = len(vals)
    lo_i, hi_i = min(si, ti) - 1, max(si, ti) + 1
    lo_j, hi_j = min(sj, tj) - 1, max(sj, tj) + 1
    width = hi_i - lo_i + 1
    height = hi_j - lo_j + 1
    total = width * height * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]

    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci = lo_i + cell % width
        cj = lo_j + cell // width
        k = vals[q]

        # Movement along the strip path within this macrocell.
        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = ((ci + cj) & 1) == 0
        # Horizontal neighbors. For an even cell, every strip touches the
        # odd cell's left/right boundary tile; for an odd cell only its
        # boundary strip touches all the even cell's strips.
        for ni in (ci - 1, ci + 1):
            if lo_i <= ni <= hi_i:
                if even:
                    nk = 0
                    dests = (nk,)
                else:
                    if k != K - 1:
                        continue
                    dests = vals
                for other_k in dests:
                    v = node(ni, cj, other_k)
                    nd = d + 1
                    if nd < dist[v]:
                        dist[v] = nd
                        heappush(heap, (nd, v))

        # Vertical neighbors, considered through the lower/upper boundary.
        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:  # current cell is upper
                lower_even = ((ci + nj) & 1) == 0
                if lower_even:
                    if k != 0:
                        continue
                    dests = (K - 1,)
                else:
                    dests = vals
                    if k != K - 1:
                        continue
            else:  # current cell is lower
                if even:
                    if k != K - 1:
                        continue
                    dests = (0,)
                else:
                    dests = vals
            for other_k in dests:
                v = node(ci, nj, other_k)
                nd = d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

    return dx + dy

