    heap = [(0, source)]

    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci = lo_i + cell % width
        cj = lo_j + cell // width
        k = vals[q]
        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = ((ci + cj) & 1) == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                # The odd neighbor's boundary tile is at its left edge for
                # an eastward crossing, and at its right edge westward.
                nk = 0 if ni > ci else K - 1
                dests = (nk,)
            else:
                # The current odd cell must use the edge stripe facing the
                # even neighbor.
                required = K - 1 if ni > ci else 0
                if k != required:
                    continue
                dests = vals
            for other_k in dests:
                v = node(ni, cj, other_k)
                nd = d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:
                lower_even = ((ci + nj) & 1) == 0
                if lower_even:
                    if k != 0:
                        continue
                    dests = (K - 1,)
                else:
                    if k != K - 1:
                        continue
                    dests = vals
            else:
                if even:
                    if k != K - 1:
                        continue
                    dests = (0,)
                else:
                    dests = vals
            for other_k in dests:
                v = node(ci, nj, other_k)
                nd = d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

    return dx + dy

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in AtCoder's wallpaper pattern.

    The pattern is divided by vertical lines x = n, horizontal lines y = n
    for even n, and diagonal lines x + y = n for even n. The region containing
    (0.5, 0.5) is black. The rectangle has opposite corners (A, B) and (C, D).
    """
    # Twice the black area in each unit square, indexed by y then x.
    # The arrangement and colors repeat every 4 units horizontally and
    # 2 units vertically.
    weights = (
        (2, 1, 0, 1),
        (1, 2, 1, 0),
    )

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)

        total = qx * qy * 8

        for j in range(ry):
            total += qx * sum(weights[j])

        for i in range(rx):
            total += qy * sum(weights[j][i] for j in range(2))

        for j in range(ry):
            for i in range(rx):
                total += weights[j][i]

        return total

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

