def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] whose digit sums are in [min_sum, max_sum].

    The result is returned modulo 10^9 + 7.
    """
    mod = 1_000_000_007

    def decrement(value: str) -> str:
        digits = list(value)
        i = len(digits) - 1
        while digits[i] == "0":
            digits[i] = "9"
            i -= 1
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    def count_at_most(bound: str) -> int:
        bound = bound.lstrip("0") or "0"
        limit = min(max_sum, 9 * len(bound))
        if min_sum > limit:
            return 0

        # less[s] counts prefixes already below the bound with digit sum s.
        less = [0] * (limit + 1)
        equal = [0] * (limit + 1)
        equal[0] = 1

        for char in bound:
            bound_digit = int(char)
            next_less = [0] * (limit + 1)
            next_equal = [0] * (limit + 1)

            for total, ways in enumerate(less):
                if ways:
                    upto = min(9, limit - total)
                    for digit in range(upto + 1):
                        next_less[total + digit] = (
                            next_less[total + digit] + ways
                        ) % mod

            for total, ways in enumerate(equal):
                if not ways:
                    continue
                upto = min(bound_digit - 1, limit - total)
                for digit in range(upto + 1):
                    next_less[total + digit] = (
                        next_less[total + digit] + ways
                    ) % mod
                if total + bound_digit <= limit:
                    next_equal[total + bound_digit] = ways

            less, equal = next_less, next_equal

        return (sum(less[min_sum:limit + 1]) +
                sum(equal[min_sum:limit + 1])) % mod

    return (count_at_most(num2) - count_at_most(decrement(num1))) % mod

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        return y % K if (i + (y // K)) % 2 == 0 else x % K

    sk = stripe(si, S_x, S_y)
    tk = stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if (dx + 1) * (dy + 1) > 100_000:
        return dx + dy

    vals = sorted({0, K - 1, sk, tk})
    vid = {v: n for n, v in enumerate(vals)}
    nvals = len(vals)
    lo_i, hi_i = min(si, ti) - 1, max(si, ti) + 1
    lo_j, hi_j = min(sj, tj) - 1, max(sj, tj) + 1
    width = hi_i - lo_i + 1
    total = width * (hi_j - lo_j + 1) * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]

    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci = lo_i + cell % width
        cj = lo_j + cell // width
        k = vals[q]
        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = ((ci + cj) & 1) == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                nk = 0 if ni > ci else K - 1
                dests = (nk,)
            else:
                required = K - 1 if ni > ci else 0
                if k != required:
                    continue
                dests = vals
            for other_k in dests:
                v = node(ni, cj, other_k)
                nd = d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:  # current cell is upper
                lower_even = ((ci + nj) & 1) == 0
                if lower_even:
                    # Any upper odd tile meets the lower even top tile.
                    dests = (K - 1,)
                else:
                    # The upper even bottom tile meets every lower odd tile.
                    if k != 0:
                        continue
                    dests = vals
            else:  # current cell is lower
                if even:
                    if k != K - 1:
                        continue
                    dests = vals
                else:
                    dests = (0,)
            for other_k in dests:
                v = node(ci, nj, other_k)
                nd = d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

    return dx + dy

