from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        return y % K if (i + y // K) % 2 == 0 else x % K

    sk, tk = stripe(si, S_x, S_y), stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if (dx + 1) * (dy + 1) > 100_000:
        return dx + dy

    vals = sorted({0, K - 1, sk, tk})
    vid, nvals = {v: n for n, v in enumerate(vals)}, len(vals)
    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    width = hi_i - lo_i + 1
    total = width * (hi_j - lo_j + 1) * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci, cj, k = lo_i + cell % width, lo_j + cell // width, vals[q]

        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = (ci + cj) % 2 == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                dests = (0 if ni > ci else K - 1,)
            else:
                if k != (K - 1 if ni > ci else 0):
                    continue
                dests = vals
            for other_k in dests:
                v, nd = node(ni, cj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:
                if (ci + nj) % 2 == 0:
                    dests = (K - 1,)
                else:
                    if k != 0:
                        continue
                    dests = vals
            elif even:
                if k != K - 1:
                    continue
                dests = vals
            else:
                dests = (0,)
            for other_k in dests:
                v, nd = node(ci, nj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))
    return dx + dy

def count_polish_sequences(n: int, a: list[int]) -> int:
    """ Count Polish sequences of length n lexicographically at most a, modulo 998244353.

    A Polish sequence is the preorder list of child counts in an ordered forest
    consisting of one tree. The singleton sequence (0) is Polish.
    """
    mod = 998244353
    # Forest counts use binomial coefficients with a top argument at most 2n.
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % mod
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], mod - 2, mod)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % mod
    inv = [0] * (n + 1)
    for i in range(1, n + 1):
        inv[i] = fact[i - 1] * invfact[i] % mod

    def choose(total: int, k: int) -> int:
        if k < 0 or total < k:
            return 0
        return fact[total] * invfact[k] % mod * invfact[total - k] % mod

    def forest_count(length: int, roots: int) -> int:
        # The cycle lemma gives roots/length times the unrestricted degree words.
        if length == 0:
            return int(roots == 0)
        if roots <= 0 or roots > length:
            return 0
        return roots * inv[length] % mod * choose(
            2 * length - roots - 1, length - 1
        ) % mod

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1
        if remaining == 0:
            # At the last position only the unique value that closes the tree
            # contributes as a smaller choice.
            x = 1 - slots
            if 0 <= x < bound:
                answer += 1
        else:
            lo = max(0, 2 - slots)  # resulting forest must have at least one root
            hi = min(bound - 1, remaining - slots + 1)
            for x in range(lo, hi + 1):
                roots = slots - 1 + x
                answer += forest_count(remaining, roots)
            answer %= mod

        slots += bound - 1
        if remaining == 0:
            if slots == 0:
                answer = (answer + 1) % mod
            break
        if slots <= 0 or slots > remaining:
            break

    return answer % mod

