def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits to partition s into k semi-palindromes."""
    n = len(s)
    # cost[i][j] is the minimum edit count for the half-open substring
    # s[i:j]. A valid spacing d must be a proper divisor of its length.
    cost = [[0] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            length = j - i
            best = length
            for d in range(1, length):
                if length % d:
                    continue
                edits = 0
                for residue in range(d):
                    count = (length - 1 - residue) // d + 1
                    for q in range(count // 2):
                        left = i + residue + q * d
                        right = i + residue + (count - 1 - q) * d
                        if s[left] != s[right]:
                            edits += 1
                if edits < best:
                    best = edits
            cost[i][j] = best

    inf = n + 1
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for parts in range(1, k + 1):
        # Each segment has length at least two.
        for end in range(2 * parts, n + 1):
            for start in range(2 * (parts - 1), end - 1):
                if dp[parts - 1][start] < inf:
                    dp[parts][end] = min(
                        dp[parts][end],
                        dp[parts - 1][start] + cost[start][end],
                    )
    return dp[k][n]

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """ Count the number of powerful integers in the range [start, finish].

    A positive integer x is called powerful if:
    1. It ends with s (s is a suffix of x)
    2. Each digit in x is at most limit
    """
    if start > finish or finish < 1 or limit < 0 or not s:
        return 0
    if any(not ch.isdigit() for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        digits = str(bound)
        m = len(s)
        total = 0

        # Count all valid numbers with fewer digits than bound.
        for length in range(max(m, 1), len(digits)):
            prefix_len = length - m
            if prefix_len == 0:
                if s[0] != "0":
                    total += 1
            else:
                total += limit * (limit + 1) ** (prefix_len - 1)

        length = len(digits)
        if length < m:
            return total
        prefix_len = length - m

        if prefix_len == 0:
            if s[0] != "0" and int(s) <= bound:
                total += 1
            return total

        bound_prefix = digits[:prefix_len]
        # Count valid prefix numbers strictly below bound_prefix.
        for i, ch in enumerate(bound_prefix):
            lo = 1 if i == 0 else 0
            remaining = prefix_len - i - 1
            choices = sum(1 for d in range(lo, limit + 1) if d < int(ch))
            total += choices * (limit + 1) ** remaining
            d = int(ch)
            if d < lo or d > limit:
                return total

        # The equal prefix is permitted only when the fixed suffix is no
        # greater than the remaining digits of the bound.
        if s <= digits[prefix_len:]:
            total += 1
        return total

    return count_up_to(finish) - count_up_to(start - 1)

