from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    total_patterns = K ** M
    if comb(N, M) < total_patterns - 1:
        return 0

    full_mask = (1 << total_patterns) - 1
    if len(X) == M and all(1 <= value <= K for value in X):
        code = 0
        for value in X:
            code = code * K + value - 1
        wanted = full_mask ^ (1 << code)
    else:
        wanted = full_mask

    # A state stores the set of all subsequences of each length seen so far,
    # encoded as a bit mask of base-K word indices.
    start = (0,) * (M + 1)
    dp = {start: 1}
    answer = 0

    for depth in range(1, N + 1):
        nxt = {}
        for state, ways in dp.items():
            for c in range(K):
                masks = list(state)
                masks[1] |= 1 << c
                for length in range(2, M + 1):
                    old = state[length - 1]
                    while old:
                        bit = old & -old
                        old -= bit
                        code = (bit.bit_length() - 1) * K + c
                        masks[length] |= 1 << code
                key = tuple(masks)
                count = nxt.get(key, 0) + ways
                nxt[key] = count % MOD
        dp = {}
        remaining = N - depth
        for state, ways in nxt.items():
            if state[M] == wanted:
                answer = (answer + ways * pow(K, remaining, MOD)) % MOD
            else:
                dp[state] = ways
        if not dp:
            break

    return answer

