from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        return y % K if (i + y // K) % 2 == 0 else x % K

    sk, tk = stripe(si, S_x, S_y), stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if (dx + 1) * (dy + 1) > 100_000:
        return dx + dy

    if K <= 100:
        vals = list(range(K))
    else:
        vals = sorted({0, K - 1, sk, tk})
    vid, nvals = {v: n for n, v in enumerate(vals)}, len(vals)
    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    width = hi_i - lo_i + 1
    total = width * (hi_j - lo_j + 1) * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci, cj, k = lo_i + cell % width, lo_j + cell // width, vals[q]

        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = (ci + cj) % 2 == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                dests = (0 if ni > ci else K - 1,)
            else:
                if k != (K - 1 if ni > ci else 0):
                    continue
                dests = vals
            for other_k in dests:
                v, nd = node(ni, cj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:
                if (ci + nj) % 2 == 0:
                    dests = (K - 1,)
                else:
                    if k != 0:
                        continue
                    dests = vals
            elif even:
                if k != K - 1:
                    continue
                dests = vals
            else:
                dests = (0,)
            for other_k in dests:
                v, nd = node(ci, nj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))
    return dx + dy

def sum_concatenated_permutations(n: int) -> int:
    """Sum all concatenations of permutations of 1..n modulo 998244353."""
    MOD = 998244353
    ROOT = 3

    def ntt(a, invert):
        size = len(a)
        j = 0
        for i in range(1, size):
            bit = size >> 1
            while j & bit:
                j ^= bit
                bit >>= 1
            j ^= bit
            if i < j:
                a[i], a[j] = a[j], a[i]
        length = 2
        while length <= size:
            wlen = pow(ROOT, (MOD - 1) // length, MOD)
            if invert:
                wlen = pow(wlen, MOD - 2, MOD)
            half = length >> 1
            for start in range(0, size, length):
                w = 1
                for k in range(start, start + half):
                    u = a[k]
                    v = a[k + half] * w % MOD
                    s = u + v
                    if s >= MOD:
                        s -= MOD
                    d = u - v
                    if d < 0:
                        d += MOD
                    a[k] = s
                    a[k + half] = d
                    w = w * wlen % MOD
            length <<= 1
        if invert:
            inv_size = pow(size, MOD - 2, MOD)
            for i in range(size):
                a[i] = a[i] * inv_size % MOD

    def multiply(a, b):
        result_len = len(a) + len(b) - 1
        if min(len(a), len(b)) <= 32 or len(a) * len(b) <= 4096:
            out = [0] * result_len
            for i, x in enumerate(a):
                if x:
                    for j, y in enumerate(b):
                        out[i + j] = (out[i + j] + x * y) % MOD
            return out
        size = 1
        while size < result_len:
            size <<= 1
        fa = a + [0] * (size - len(a))
        fb = b + [0] * (size - len(b))
        ntt(fa, False)
        ntt(fb, False)
        for i in range(size):
            fa[i] = fa[i] * fb[i] % MOD
        ntt(fa, True)
        return fa[:result_len]

    counts = {}
    value_sums = {}
    for x in range(1, n + 1):
        digits = 1 if x < 10 else 2 if x < 100 else 3 if x < 1000 else 4 if x < 10000 else 5 if x < 100000 else 6
        counts[digits] = counts.get(digits, 0) + 1
        value_sums[digits] = value_sums.get(digits, 0) + x

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    poly = [1]
    rates = {}
    for digits, count in counts.items():
        rate = pow(10, digits, MOD)
        rates[digits] = rate
        group_poly = [0] * (count + 1)
        power = 1
        for k in range(count + 1):
            group_poly[k] = fact[count] * invfact[k] % MOD * invfact[count - k] % MOD * power % MOD
            power = power * rate % MOD
        poly = multiply(poly, group_poly)

    answer = 0
    for digits, total in value_sums.items():
        rate = rates[digits]
        excluded = 0
        weighted = 0
        for j in range(n):
            if j == 0:
                excluded = poly[0]
            else:
                excluded = (poly[j] - rate * excluded) % MOD
            weighted = (weighted + excluded * fact[j] % MOD * fact[n - j - 1]) % MOD
        answer = (answer + total * weighted) % MOD
    return answer

from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    total_patterns = K ** M
    if comb(N, M) < total_patterns - 1:
        return 0

    # With a binary alphabet and pairs as targets, omitting aa requires at most
    # one a. The other three pairs are all present exactly when that lone a is
    # strictly between two or more copies of the other symbol.
    if M == 2 and K == 2:
        if len(X) != 2 or not all(1 <= value <= 2 for value in X):
            return 0
        if X[0] == X[1]:
            return max(0, N - 2)
        # A missing mixed pair forces at least one of the two constant pairs
        # also to be absent, so exactly one missing pair is impossible.
        return 0

    full_mask = (1 << total_patterns) - 1
    if len(X) == M and all(1 <= value <= K for value in X):
        code = 0
        for value in X:
            code = code * K + value - 1
        wanted = full_mask ^ (1 << code)
    else:
        wanted = full_mask

    # Each mask records which words of a given length occur as subsequences.
    start = (0,) * (M + 1)
    dp = {start: 1}
    answer = 0

    for depth in range(1, N + 1):
        nxt = {}
        for state, ways in dp.items():
            for c in range(K):
                masks = list(state)
                masks[1] |= 1 << c
                for length in range(2, M + 1):
                    old = state[length - 1]
                    while old:
                        bit = old & -old
                        old -= bit
                        code = (bit.bit_length() - 1) * K + c
                        masks[length] |= 1 << code
                key = tuple(masks)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = {}
        remaining = N - depth
        multiplier = pow(K, remaining, MOD)
        for state, ways in nxt.items():
            if state[M] == wanted:
                answer = (answer + ways * multiplier) % MOD
            else:
                dp[state] = ways
        if not dp:
            break

    return answer

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        return y % K if (i + y // K) % 2 == 0 else x % K

    sk, tk = stripe(si, S_x, S_y), stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0
    dx, dy = abs(ti - si), abs(tj - sj)
    if (dx + 1) * (dy + 1) > 100_000:
        return dx + dy

    vals = list(range(K)) if K <= 100 else sorted({0, K - 1, sk, tk})
    vid, nvals = {v: n for n, v in enumerate(vals)}, len(vals)
    margin = K if K <= 100 else 2
    lo_i, hi_i = min(si, ti) - margin, max(si, ti) + margin
    lo_j, hi_j = min(sj, tj) - margin, max(sj, tj) + margin
    width = hi_i - lo_i + 1
    total = width * (hi_j - lo_j + 1) * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci, cj, k = lo_i + cell % width, lo_j + cell // width, vals[q]

        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = (ci + cj) % 2 == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                dests = (0 if ni > ci else K - 1,)
            else:
                if k != (K - 1 if ni > ci else 0):
                    continue
                dests = vals
            for other_k in dests:
                v, nd = node(ni, cj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:
                if (ci + nj) % 2 == 0:
                    dests = (K - 1,)
                else:
                    if k != 0:
                        continue
                    dests = vals
            elif even:
                if k != K - 1:
                    continue
                dests = vals
            else:
                dests = (0,)
            for other_k in dests:
                v, nd = node(ci, nj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))
    return dx + dy

