from functools import lru_cache
from math import comb, factorial

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    total_patterns = K ** M
    if comb(N, M) < total_patterns - 1:
        return 0

    x_valid = len(X) == M and all(1 <= value <= K for value in X)
    x = tuple(value - 1 for value in X) if x_valid else ()

    # At length MK-1, omitting one constant word is the unique way to attain
    # all other patterns: the word has M arches, each a permutation of the
    # other K-1 symbols, separated by M-1 copies of the omitted symbol.
    if N == M * K - 1:
        if x_valid and len(set(x)) == 1:
            return pow(factorial(K - 1), M, MOD)
        return 0

    if M == 2 and K == 2:
        if not x_valid:
            return 0
        if x[0] == x[1]:
            return max(0, N - 2)
        return 0

    if x_valid:
        code = 0
        for value in x:
            code = code * K + value
        wanted = ((1 << total_patterns) - 1) ^ (1 << code)
    else:
        wanted = (1 << total_patterns) - 1

    @lru_cache(None)
    def suffix_avoidance(q: int, length: int) -> int:
        if not x_valid:
            return pow(K, length, MOD)
        ways = [0] * (M + 1)
        ways[q] = 1
        for _ in range(length):
            nxt = [0] * (M + 1)
            for matched in range(M):
                count = ways[matched]
                if count:
                    for c in range(K):
                        new_matched = matched + (c == x[matched])
                        if new_matched < M:
                            nxt[new_matched] = (nxt[new_matched] + count) % MOD
            ways = nxt
        return sum(ways[:M]) % MOD

    prefix_codes = []
    if x_valid:
        for q in range(1, M + 1):
            code = 0
            for value in x[:q]:
                code = code * K + value
            prefix_codes.append((q, code))

    def matched_prefix(state):
        for q, code in reversed(prefix_codes):
            if state[q] >> code & 1:
                return q
        return 0

    start = (0,) * (M + 1)
    dp = {start: 1}
    answer = 0

    for depth in range(1, N + 1):
        nxt = {}
        for state, ways in dp.items():
            for c in range(K):
                masks = list(state)
                masks[1] |= 1 << c
                for length in range(2, M + 1):
                    old = state[length - 1]
                    while old:
                        bit = old & -old
                        old -= bit
                        code = (bit.bit_length() - 1) * K + c
                        masks[length] |= 1 << code
                key = tuple(masks)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = {}
        remaining = N - depth
        for state, ways in nxt.items():
            if state[M] == wanted:
                q = matched_prefix(state)
                answer = (answer + ways * suffix_avoidance(q, remaining)) % MOD
            else:
                dp[state] = ways
        if not dp:
            break

    return answer

