from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are indexed by integers (i, j, k), with 0 <= k < K. If i and j
    have the same parity, a tile covers [iK, (i+1)K] x [jK+k, jK+k+1].
    Otherwise it covers [iK+k, iK+k+1] x [jK, (j+1)K]. Two tiles are
    adjacent when their edges share a positive-length segment.

    The coordinates S_x, S_y, T_x, and T_y identify the tiles containing
    (S_x+0.5, S_y+0.5) and (T_x+0.5, T_y+0.5), respectively.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i: int, x: int, y: int) -> int:
        return y % K if (i + y // K) % 2 == 0 else x % K

    sk, tk = stripe(si, S_x, S_y), stripe(ti, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0
    dx, dy = abs(ti - si), abs(tj - sj)
    if (dx + 1) * (dy + 1) > 1_000_000:
        return dx + dy

    vals = list(range(K)) if K <= 100 else sorted({0, K - 1, sk, tk})
    vid, nvals = {v: n for n, v in enumerate(vals)}, len(vals)
    margin = K if K <= 100 else 2
    lo_i, hi_i = min(si, ti) - margin, max(si, ti) + margin
    lo_j, hi_j = min(sj, tj) - margin, max(sj, tj) + margin
    width = hi_i - lo_i + 1
    total = width * (hi_j - lo_j + 1) * nvals

    def node(i: int, j: int, v: int) -> int:
        return ((j - lo_j) * width + (i - lo_i)) * nvals + vid[v]

    source, target = node(si, sj, sk), node(ti, tj, tk)
    dist = [10**100] * total
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        cell, q = divmod(u, nvals)
        ci, cj, k = lo_i + cell % width, lo_j + cell // width, vals[q]

        for r, other_k in enumerate(vals):
            if r != q:
                v = cell * nvals + r
                nd = d + abs(k - other_k)
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        even = (ci + cj) % 2 == 0
        for ni in (ci - 1, ci + 1):
            if not lo_i <= ni <= hi_i:
                continue
            if even:
                dests = (0 if ni > ci else K - 1,)
            else:
                if k != (K - 1 if ni > ci else 0):
                    continue
                dests = vals
            for other_k in dests:
                v, nd = node(ni, cj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        for nj in (cj - 1, cj + 1):
            if not lo_j <= nj <= hi_j:
                continue
            if nj < cj:
                if (ci + nj) % 2 == 0:
                    dests = (K - 1,)
                else:
                    if k != 0:
                        continue
                    dests = vals
            elif even:
                if k != K - 1:
                    continue
                dests = vals
            else:
                dests = (0,)
            for other_k in dests:
                v, nd = node(ci, nj, other_k), d + 1
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))
    return dx + dy

