            return pow(factorial(K - 1), M, MOD)
        return 0

    # For a distinct triple abc, let t be the last c. The prefix before t
    # contains every ordered pair except ab. After t, the first ab pair must
    # be followed by another occurrence of every alphabet symbol except c.
    if M == 3 and valid_x and len(set(x)) == 3 and K >= 3:
        a, b, c = x
        alphabet = [z for z in range(K) if z != c]
        bit_for = {z: 1 << i for i, z in enumerate(alphabet)}
